    Refresh, Refreshing, RefreshFailed, RateLimited, Installing, InstallFailed, All, Stars, Updated, Name, Empty, Uninstall,
    Scan, Scanning, ScanFailed, ScanResult, ScanHint, OpenRepo, RemovePending
}

// The GitHub source is part of the same panel as the Workshop browser, so it must speak the
// same 15 languages. Order matters: the keys above index into every row below. ScanResult is
